    $tp = json_decode((string)setting_get($pdo, 'wa_ru_tpl_pause', ''), true); $tp = is_array($tp) ? $tp : []; $rowsP = []; $cnt = ['all' => 0, 'usable utility' => 0];
    foreach ((function_exists('wa_util_pool_rows') ? wa_util_pool_rows($pdo) : []) as $k => $r) { $cnt['all']++; $why = [];
        if (!empty($r['relabelled_at'])) $why[] = 'relabelled ' . substr((string)$r['relabelled_at'], 5, 11); if (strtoupper((string)($r['category_now'] ?? '')) === 'MARKETING') $why[] = 'Meta says marketing now'; if (strtoupper((string)($r['category'] ?? '')) !== 'UTILITY') $why[] = 'category ' . $r['category'];
        if (function_exists('wa_rs_dull') && wa_rs_dull((string)($r['body'] ?? ''))) $why[] = 'basic (blocked)'; if (isset($tp[(int)$r['id']]) && (int)$tp[(int)$r['id']] > time()) $why[] = 'paused by Meta until ' . date('H:i', (int)$tp[(int)$r['id']]);
        $t = function_exists('wa_camp_tpl') ? wa_camp_tpl($pdo, (int)$r['id'], true, 0) : ['x' => 1]; if (!$t) $why[] = 'not approved on any number';
        if (!$why) $cnt['usable utility']++; $rowsP[] = [(int)$r['id'], mb_substr((string)$r['name'], 0, 30), (string)($r['pool_kind'] ?? ''), $why ? implode(' + ', $why) : 'USABLE']; }
    usort($rowsP, fn($a, $b) => ($a[3] === 'USABLE' ? 0 : 1) <=> ($b[3] === 'USABLE' ? 0 : 1)); $by = []; foreach ($rowsP as $x) { $kk = $x[2] . ' · ' . ($x[3] === 'USABLE' ? 'USABLE' : preg_replace('/ \d\d-\d\d \d\d:\d\d| until \d\d:\d\d/', '', $x[3])); $by[$kk] = ($by[$kk] ?? 0) + 1; } arsort($by);
    echo "ASK BPOOL " . json_encode($cnt) . " · by kind and state " . json_encode($by, JSON_UNESCAPED_UNICODE) . " · usable ones " . json_encode(array_values(array_filter($rowsP, fn($x) => $x[3] === 'USABLE')), JSON_UNESCAPED_UNICODE) . " · recently lost (first 12 not usable) " . json_encode(array_slice(array_values(array_filter($rowsP, fn($x) => $x[3] !== 'USABLE' && strpos($x[1], 'rs') === 0)), 0, 12), JSON_UNESCAPED_UNICODE) . "\n";
} catch (Throwable $e) { echo "ASK BPOOL ERR " . substr($e->getMessage(), 0, 140) . "\n"; }
// THE RESPONSE TO THE FAST OFFER (owner 26 Nov: "send in 1-3 minutes and see what response comes"): offers of the last 3 days by the wait after his reply; did he write again within 6 hours of the offer (counts only)
try { $b = [['<= 5 min', 0, 5], ['6-19 min', 6, 19], ['20-60 min', 20, 60], ['over 60 min', 61, 100000]]; $o = []; $x3 = date('Y-m-d H:i:s', time() - 3 * 86400);
    foreach ($b as [$lab, $lo, $hi]) { $q = $pdo->prepare("SELECT COUNT(*), SUM(EXISTS (SELECT 1 FROM wa_messages m WHERE m.phone = o.phone COLLATE utf8mb4_unicode_ci AND m.dir = 'in' AND m.ts > o.at AND m.ts <= DATE_ADD(o.at, INTERVAL 6 HOUR))) FROM wa_offer o WHERE o.mode = 'live' AND o.ok = 1 AND o.at >= ? AND o.reply_at IS NOT NULL AND TIMESTAMPDIFF(MINUTE, o.reply_at, o.at) BETWEEN ? AND ? AND o.at <= ?"); $q->execute([$x3, $lo, $hi, date('Y-m-d H:i:s', time() - 6 * 3600)]); $r = $q->fetch(PDO::FETCH_NUM); $o[$lab] = ['offers' => (int)$r[0], 'wrote again in 6 h' => (int)$r[1], 'rate' => (int)$r[0] > 0 ? round(100 * (int)$r[1] / (int)$r[0], 1) . '%' : '-']; }
    $f = $pdo->query("SELECT COUNT(*), AVG(TIMESTAMPDIFF(SECOND, reply_at, at)) FROM wa_offer WHERE mode = 'live' AND ok = 1 AND at >= '" . date('Y-m-d H:i:s', time() - 3600) . "'")->fetch(PDO::FETCH_NUM);   /* the shop's clock, not the database's (NOW() is UTC there: it showed the evening's offers as 'the last hour') */
    echo "ASK OFFERFAST " . json_encode($o) . " · offers in the last 60 min " . (int)$f[0] . " · their average wait " . round((float)$f[1]) . " s · wo_fast " . (string)setting_get($pdo, 'wo_fast', '1') . "\n"; } catch (Throwable $e) { echo "ASK OFFERFAST ERR " . substr($e->getMessage(), 0, 120) . "\n"; }
